CREATE TABLE scores(score INTEGER);
INSERT INTO scores VALUES(22),(12),(4),(NULL);
CREATE TEMP VIEW shown AS
SELECT score,CASE WHEN score IS NULL THEN 'unknown' WHEN score>=20 THEN 'high' WHEN score>=10 THEN 'middle' ELSE 'low' END AS band
FROM scores;
